HERE = os.path.dirname(os.path.abspath(__file__))
WEB = os.path.join(HERE, "..", "WebPages")
CSS_SRC = os.path.join(WEB, "topic-01-lecture.html")
OUT = os.path.join(WEB, "topic-04-lecture.html")
DECK = "topic-04.html"


def _css():
    """⛔ 逐字稿样式必须插在 </style> **之前** ——&nbsp;
    拼在后面就变成页面上的字面文本，而**构建照样成功**。"""
    h = io.open(CSS_SRC, encoding="utf-8").read()
    i, end = h.index("<style>"), h.index("</style>")
    out = h[i:end] + """
details.oral{border:1px solid #a8dab5;border-left:4px solid #1e8e3e;border-radius:8px;
  background:#f6fbf7;margin:16px 0;padding:0}
details.oral>summary{cursor:pointer;padding:10px 14px;font-weight:700;color:#0d652d}
details.oral[open]{background:#fff}
details.oral .body{padding:2px 16px 14px}
details.oral .body p{margin:10px 0;line-height:1.9}
""" + "</style>"
    assert "details.oral{" in out and out.count("</style>") == 1, \
        "逐字稿样式没插进 <style> 里"
    return out


