# ── 时间账：从成品 HTML 现数，别手写常数 ────────────────────────────
_say = "".join(re.sub(r"<[^>]+>", "", m)
               for m in re.findall(r'<p class="say[^"]*">(.*?)</p>', html, re.S))
_n = len(re.findall(r"[一-鿿]", _say))
_cuts = len(re.findall(r'<p class="board">', html))
_smin, _cmin = _n / 200.0, _cuts * 15 / 60.0
_tot = _smin + _cmin

_secs = [(m.start(), re.sub(r"<[^>]+>", "", m.group(1)))
         for m in re.finditer(r'<h3 class="sec"[^>]*>(第[零一二三四五六]节.*?)</h3>', html)]
assert len(_secs) == 7, "节标题只找到 %d 个" % len(_secs)
_secs.append((html.index("🚧 这份讲义还薄"), ""))
_rows, _floor = [], 0.0
_over_rows = []          # ⭐ 地板超过计划的节，build 时喊出来
for _i in range(7):
    _t = html[_secs[_i][0]:_secs[_i + 1][0]]
    _cn = len(re.findall(r"[一-鿿]", "".join(
        re.sub(r"<[^>]+>", "", x)
        for x in re.findall(r'<p class="say[^"]*">(.*?)</p>', _t, re.S))))
    _cc = len(re.findall(r'<p class="board">', _t))
    _f = _cn / 200.0 + _cc * 0.25
    _floor += _f
    _plan = re.search(r"（(\d+)′", _secs[_i][1])
    _plan = int(_plan.group(1)) if _plan else 0
    _bad = ' style="color:#c5221f;font-weight:700"' if _f > _plan else ""
    if _f > _plan + 0.5:
        _over_rows.append((_secs[_i][1].split("　")[0], _f, _plan))
    _rows.append("<tr><td>%s</td><td>%s</td><td>%d</td>"
                 "<td%s>%.1f′</td><td>%d′</td></tr>"
                 % (_secs[_i][1].split("（")[0], format(_cn, ","), _cc, _bad, _f, _plan))
_floorhtml = ('<table><thead><tr><th>节</th><th>台词汉字</th><th>切图</th>'
              '<th>地板</th><th>计划给的</th></tr></thead><tbody>'
              + "".join(_rows)
              + '<tr><td><b>七节合计</b></td><td colspan="2"></td>'
                '<td><b>%.0f′</b></td><td><b>83′</b></td></tr>' % _floor
              + "</tbody></table>")
html = html.replace("@@FLOOR@@", _floorhtml)
assert _n > 3000 and _cuts > 8, "时间账数出来不对劲：%d 字 / %d 切图" % (_n, _cuts)
for _k, _v in (("@@SAY@@", format(_n, ",")), ("@@SAYMIN@@", "%.0f" % _smin),
               ("@@CUTS@@", str(_cuts)), ("@@CUTMIN@@", "%.1f" % _cmin),
               ("@@TOTAL@@", "%.0f" % _tot),
               ("@@BUF70@@", "%.0f" % (80 - _tot))):
    assert _k in html, "时间账占位符 %s 不在文里了" % _k
    html = html.replace(_k, _v)

# ⛔⛔ 2026-09-19 T18：时间表的「合计」跟各行对不上过（各行 77，合计写 80）。
#   一张自己加不起来的时间表，台上照着分时间会分错，而且它看起来完全正常。
#   ⭐ 判据：**任何「分项 ＋ 合计」的表，都要断言分项之和等于合计。**
_mins = [int(x) for x in re.findall(
    r'<td[^>]*>(?:<b>)?[零一二三四五六][　\s][^<]*(?:</b>)?</td>\s*<td[^>]*>(?:<b>)?(\d+)',
    html)]
_sum = re.search(r'<td><b>合计</b></td><td><b>(\d+)</b></td>', html)
assert _mins and _sum, "⛔ 时间表没解析到（%d 行 / 合计 %s）" % (len(_mins), bool(_sum))
assert sum(_mins) == int(_sum.group(1)), \
    "时间表加不起来：各行 %s ＝ %d，合计写着 %s" % (_mins, sum(_mins), _sum.group(1))
print("   ✅ 时间表 %s ＝ %d 分，跟合计一致" % ("＋".join(map(str, _mins)), sum(_mins)))

# ⛔⛔⛔ 2026-09-20 第 18 轮：上面那条只查了「分项之和 ＝ 合计」，
#   **没查另一套数**。而超时警报用的恰恰是另一套 ——&#160;节标题里的
#   （3/15/15/20/8/12/10 ＝ 83′），那是早就作废的版本。
#   后果两头都错：第一节被虚报超 8.5′（按 22′ 只超 1.5′），
#   第四节真超了却一声不吭（地板 3.2′ > 给 2′）。
#   ⭐ 判据：**同一个量有两处写法时，「求和自洽」证明不了任何事** ——&#160;
#     两套各自都能自洽，还是对不上。要断的是**两套之间**。
# ══════════════════════════════════════════════════════════════════════
# ⭐⭐⭐ 2026-09-22 现场把讲稿的风格判据说死了，原话：
#   「你这个在这给我捋数字呢？这个就听不太懂。换一个平易近人的方式讲。」
#   重讲之后：「这个讲法就非常好，**我们这个就是要科普，不是要把那个数
#   挨个的捋一遍，就是知道那个意思**，这很重要。」
#
# ⭐ 判据：**报数之前先问一句 —— 这个数是「内容」，还是「内容的证据」。**
#   · 是内容 → 报（例：一层 MoE 块 1.73 GiB，那一格讲的就是这个数）
#   · 是证据 → 说「有人把它量出来了」就够，**具体值留给课件**
#     （例：三个种子各跑几次、质量分各是多少 —— 台下一个都记不住）
#
# ⛔ 台词里连着报三个以上的数，基本就是在捋数。下面这条把它量出来：
#   按 `<p class="say">` 逐块算「每百汉字几个数字」，超线的列出来。
# ⚠️ **只报告不拦截** —— 有些块天生就该有数（口算总账那种）。
#   它的作用是「让人看得见」，判断还是人做。
#
# ⭐⭐ 为什么这条 lint **只装在讲义上、不装在课件上**：
#   课件是**看**的 —— 一个数摆在那儿，读者可以停下来、回头看、自己核。
#   讲义是**念**的 —— 一串数从耳朵进去，台下一个都留不住，
#   而且它们会**挤掉那句真正要带走的话**。
#   ⛔ 同一个数，在课件里是资料，在台上就是噪音。两边不是一条判据。
_SAY_DIGIT_LIMIT = 12.0          # 每百汉字的数字个数，超了就点名
_noisy = []
for _b in re.findall(r'<p class="say">(.*?)</p>', html, re.S):
    _t = re.sub(r"<[^>]+>", "", _b).replace("&nbsp;", " ")
    _c = len(re.findall(r"[一-鿿]", _t))
    if _c < 40:
        continue
    # ⛔ 2026-09-22 第一版就有假阳性：它把 **名字里的数字** 也数了 ——
    #   bf16 / fp16 / fp32 / GPT-3 / ZeRO-1 / H100 里的数字不是「报数」，
    #   它们是这个东西的名字。于是「bf16 要不要 loss scaling」那一格
    #   被判成全场第三密，而它其实一个量都没报。
    # ⭐ 判据：**度量之前先问它数的是不是你想数的东西。**
    #   （这一轮自己就在同一件事上栽过三次：HKT 当 UTC、把自己的命令
    #    也 grep 进去、拿没时间戳的行做时间比较。）
    _probe = re.sub(r"[A-Za-z]+-?[0-9]+", "", _t)      # 先摘掉带数字的名字
    _d = len(re.findall(r"[0-9]", _probe))
    if _d * 100.0 / _c > _SAY_DIGIT_LIMIT:
        _noisy.append((_d * 100.0 / _c, _d, _c, re.sub(r"\s+", " ", _t)[:40]))

# ⭐⭐ 2026-09-22 全篇炼钢时加的：**已判定「数就是内容」的段，单独列一栏。**
#   不加这个的话，每次全篇过一遍都会被同样这三段拦一次，
#   而它们**恰恰是不能改的** —— 它们是台下跟着一起算的例题：
#     · 推子那一格（0.01 → 4.00 → 4.03 → 兑换率 3）：这是「导数」的定义现场
#     · 「4.00 是值，3 是兑换率」：这一格的全部内容就是这两个数的区别
#     · 「加一千次还是 1.0」：这是那个实验本身，去掉数就没有实验了
#   ⛔ 判据：**报数之前先问「这个数是内容还是证据」——&#160;
#      而判完之后要把结论写下来，否则下一轮又从头判一次。**
_JUDGED_CONTENT = ("把一个参数想象成", "注意 —— 导数不是", "有人会想：那多加几次")
_ok = [n for n in _noisy if n[3].strip().lstrip("「").startswith(_JUDGED_CONTENT)]
_noisy = [n for n in _noisy if n not in _ok]
if _noisy:
    _noisy.sort(reverse=True)
    print("   ⚠️  台词里数字偏密的段（每百汉字 > %.0f 个）：" % _SAY_DIGIT_LIMIT)
    for _r, _d, _c, _x in _noisy:
        print("       %5.1f  (%2d 个数 / %3d 字)  %s…" % (_r, _d, _c, _x))
    print("       ⭐ 判据：这个数是**内容**还是**内容的证据**？"
          "是证据就别念，留给课件。")
else:
    print("   ✅ 台词里没有「数字是证据却拿来念」的段")
if _ok:
    print("   ✅ 另有 %d 段密度超标但**已判定数字就是内容**（台下跟着一起算的例题），"
          "不改：" % len(_ok))
    for _r, _d, _c, _x in _ok:
        print("       %5.1f  %s…" % (_r, _x))

_head_min = [int(m) for m in re.findall(r"第[零一二三四五六]节[^（<]*（(\d+)′", html)]
assert _head_min == _mins, (
    "两套计划时长对不上 ——&#160;超时警报会拿错的那套去比：\n"
    "  节标题：%s ＝ %d′\n  时间表：%s ＝ %d′"
    % (_head_min, sum(_head_min), _mins, sum(_mins)))

# ⛔⛔ 三套时长并存，而原来没有任何一条检查它们**互相**对不对得上：
#   ① 压缩版（上面那张「愿望」表）  ② 节标题里写的  ③ 地板（台词念完 ＋ 切图滚动）
#   ✅ 2026-09-20 第 18 轮：①②**已经合并成一套**并加了断言（见上面）。
#     现在只剩「计划」与「地板」两套，而它们本来就该不一样 ——&#160;差多少就是欠多少。
#   ⭐ 地板是唯一不由人定的 ——&#160;它由字数算出来。所以它超过计划时，
#     超的不是「讲得慢」，是**稿子本身写超了**。
#   （2026-09-20 第 6 轮开讲时发现：给第一节加了三分钟残差台词之后，
#    地板 85→87，而计划一直没人动。）
if _over_rows:
    print("   ⚠️  地板超过计划的节（照稿一字不落念完就超时）：")
    for _nm, _fl, _pl in _over_rows:
        print("       %-22s 地板 %5.1f′ > 给 %2d′   超 %.1f′" % (_nm, _fl, _pl, _fl - _pl))
    print("       ⛔ 合计地板 %.0f′ ——&#160;要么砍稿，要么改计划" % _floor)

# ══════════════════════════════════════════════════════════════════════
# ⛔⛔ 2026-09-22 立：**讲稿里报的每一个大数，教材页面上必须也有。**
#
# 起因：这一天把 MoE 激活账改了口径（「派发九份」作废），教材那边
# 一行改动全篇自动重算 —— 而讲稿里的 4.15 TiB / 177.89 GiB 是**手打的**，
# 一个都没跟着动。于是台上会念一组页面上已经不存在的数。
#
# ⭐ 已有的「讲义覆盖体检」只对**小节号**，它自己的输出里就写着
#   「⚠️ 本 lint 只对小节号，对不了讲稿内容是否过期」—— 这条补的正是那个洞。
# ⚠️ 只查这一小撮**头号数字**，不求全：查得太宽会因为四舍五入天天误报，
#   而误报会把真问题淹掉。
_DECK = os.path.join(WEB, "topic-04.html")
if os.path.exists(_DECK):
    _deck = re.sub(r"\s+", "", io.open(_DECK, encoding="utf-8").read())
    _say = re.sub(r"\s+", "", re.sub(r"<[^>]+>", "", html))
    _BIG = re.findall(r"[0-9]+\.[0-9]+(?:TiB|GiB)", _say)
    _lost = sorted({b for b in _BIG if b not in _deck})
    assert not _lost, (
        "讲稿报了教材上没有的数：%s\n"
        "  —— 教材是算出来的、讲稿是手打的，所以漂的一定是讲稿。"
        "去 topic-04.html 里对一遍再改。" % "、".join(_lost))
    print("   ✅ 讲稿里 %d 个 TiB/GiB 量级的数，教材页面上都找得到" % len(_BIG))

# ⭐⭐⭐ 2026-09-22 新立：**一块台词不许一口气跨多个面板，也不许太长。**
#   触发事件：fig-beststep 那一格把 Ⓐ／Ⓑ／Ⓒ 三格挤在一块 say 里 ——&#160;
#   典型的「捋」。全篇一扫只有那一处，但它**不会自己保持在零**。
#   ⭐ 判据：**一块台词对应一个动作。** 跨面板就该断开，让台上有机会切屏、停顿。
#   ⚠️ 门槛按「跨 ≥2 个面板字母 **且** ≥90 汉字」算 ——&#160;
#     只提一次「看 Ⓑ 那一格」的短句不该被拦。
_MAXSAY = 200
_says = re.findall(r'<p class="say">(.*?)</p>', html, re.S)
_cram, _long = [], []
# ⛔⛔ 2026-09-22 立刻踩的坑：这个循环原来用 _t / _p / _n 当变量名，
#   而 **_n 上面存着「台词总字数」** ——&#160;循环一跑就把它覆盖成了
#   最后一块的字数，末行于是打出「台词 10 字」。
#   ⭐ 判据：**模块级脚本里加循环，先看一眼这个名字有没有人在用。**
#     函数里无所谓，模块级全是全局变量 ——&#160;而且它不报错，只是数字变了。
for _sayt in _says:
    _sayp = re.sub(r"<[^>]+>", "", _sayt).replace("&nbsp;", " ").replace("&#160;", " ")
    _sayn = len(re.findall(r"[一-鿿]", _sayp))
    if len(set(re.findall(r"[ⒶⒷⒸⒹ]", _sayp))) >= 2 and _sayn >= 90:
        _cram.append(re.sub(r"\s+", " ", _sayp)[:44])
    if _sayn > _MAXSAY:
        _long.append((_sayn, re.sub(r"\s+", " ", _sayp)[:44]))
assert not _cram, ("有台词一口气跨了多个面板（台下跟不住，台上也没法切屏）：\n  %s"
                   % "\n  ".join(_cram))
assert not _long, ("有台词超过 %d 汉字：\n  %s\n  ⭐ 一块台词对应一个动作，断开它。"
                   % (_MAXSAY, "\n  ".join("%d 字 %s…" % x for x in _long)))
print("   ✅ 没有「一口气跨多面板」或过长的台词块（共 %d 块）" % len(_says))

# ⭐⭐⭐ 2026-09-22 新立：**台上提示不许漏进台词。**
#   触发事件：fig-beststep 那一格里写着「⛔ 这里不要再展开讲二阶导……」，
#   而它**在 <p class="say"> 里面** ——&#160;照稿念会把这句念出来。
#   另一处是「（式子在课件 3.3b，台上不用念。）」，同样在台词里。
#   ⭐ 判据：**say 块里的每一个字都默认是要出口的。**
#     台上提示一律写在 say 块外面。
#   ⛔ 这类错**不报错、不出现在任何别的 lint 里**，只在真念的时候才露馅。
#   ⚠️ 判据要**只认对着讲者说的祈使句** ——&#160;第一版探针把「调音台上」
#     「看这一格」也算进去了，9 条里 8 条是假阳性。
#     （又是那条：**度量之前先问它数的是不是你想数的东西。**）
_STAGE_ONLY = ("不要在这里", "不要展开讲", "整段跳过", "别念", "台上不用念",
               "时间紧可以", "这一格不要", "别在这里", "讲之前停", "先只放")
_leak = [(w, re.sub(r"<[^>]+>", "", t)[:46])
         for t in re.findall(r'<p class="say">(.*?)</p>', html, re.S)
         for w in _STAGE_ONLY if w in t]
assert not _leak, (
    "台上提示漏进台词了（照稿念会念出来）：\n  %s\n"
    "  ⭐ say 块里的每一个字都默认是要出口的 ——&#160;提示写到 say 外面去。"
    % "\n  ".join("「%s」 在：%s…" % (w, x) for w, x in _leak))
print("   ✅ 没有台上提示漏进台词")

# ⭐⭐⭐ 2026-09-22 全篇炼钢时新立：**收尾语气只许出现在最后一节。**
#   触发事件：那四条判据（末句「数字会过期，这四条不会」）写在**第五节末尾**，
#   可后面还有一整个第六节 —— 台下听到那句会以为下课了，结果又开一节；
#   而真正的最后一节反倒没有落点。**这个缺陷没有任何构建报错，
#   读单节的时候也完全看不出来 —— 只有把整份从头念一遍才会撞上。**
#   ⭐ 判据：**「谢幕」是一种一次性资源，用在倒数第二节就等于浪费掉了。**
#   ⛔ 所以把它变成断言：收尾语句只能落在最后一个 <h3 class="sec"> 之后。
#   ⛔ 第一版立刻误报了：它扫的是整页，于是把**我自己写的那条说明**
#      （「在这儿说『数字会过期』等于提前谢幕」）当成了犯罪现场。
#   ⭐ 又是那条老判据：**度量之前先问它数的是不是你想数的东西。**
#      要查的是**台词**，不是台上提示，所以只扫 <p class="say">。
_CURTAIN = ("数字会过期", "念完就停")
#   ⛔ 第二次误报：页面末尾还有一节「🚧 这份讲义还薄的地方」，它也是
#      <h3 class="sec">，于是「最后一节」被算成了那一节。**只认带 id="cN" 的章。**
_secs = [m.start() for m in re.finditer(r'<h3 class="sec" id="c\d+"', html)]
_SAYS = [(m.start(), m.group(1)) for m in
         re.finditer(r'<p class="say">(.*?)</p>', html, re.S)]
if _secs:
    _early = sorted({w for w in _CURTAIN for _pos, _txt in _SAYS
                     if w in _txt and _pos < _secs[-1]})
    assert not _early, (
        "收尾语气出现在最后一节之前：%s\n"
        "  —— 这一讲会「谢两次幕」：台下听到收尾句以为下课了，后面却还有整整一节。\n"
        "  要么把那段挪到最后一节，要么换掉措辞。" % "、".join(_early))
    print("   ✅ 收尾语气只出现在最后一节（不会谢两次幕）")

io.open(OUT, "w", encoding="utf-8").write(html)
print("ok  topic-04-lecture.html  %s 字符 · %d 节 · 台词 %s 字 ＋ %d 切图 ＝ %.0f′"
      % (format(os.path.getsize(OUT), ","), len(CH), format(_n, ","), _cuts, _tot))
